import { useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

const ChatWidget = () => {
  const { data } = useQuery({
    queryKey: ["chat_widget_config"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("chat_widget_enabled, chat_widget_code")
        .limit(1)
        .single();
      if (error) return null;
      return data as { chat_widget_enabled: boolean; chat_widget_code: string } | null;
    },
    staleTime: 5 * 60 * 1000,
  });

  useEffect(() => {
    const containerId = "rankora-chat-widget";

    // Clean up any previous widget
    const existing = document.getElementById(containerId);
    if (existing) existing.remove();

    if (!data?.chat_widget_enabled || !data?.chat_widget_code?.trim()) return;

    // Create a container and inject the embed code
    const container = document.createElement("div");
    container.id = containerId;
    document.body.appendChild(container);

    // Parse and execute scripts from the embed code
    const temp = document.createElement("div");
    temp.innerHTML = data.chat_widget_code;

    // Move non-script nodes
    Array.from(temp.childNodes).forEach((node) => {
      if (node instanceof HTMLScriptElement) {
        const script = document.createElement("script");
        // Copy attributes
        Array.from(node.attributes).forEach((attr) =>
          script.setAttribute(attr.name, attr.value)
        );
        script.textContent = node.textContent;
        container.appendChild(script);
      } else {
        container.appendChild(node.cloneNode(true));
      }
    });

    return () => {
      const el = document.getElementById(containerId);
      if (el) el.remove();
    };
  }, [data?.chat_widget_enabled, data?.chat_widget_code]);

  return null;
};

export default ChatWidget;

