const sanitized = DOMPurify.sanitize(data.chat_widget_code, {
  ADD_TAGS: ["script", "iframe"],
  ADD_ATTR: ["src", "async", "defer", "allow", "allowfullscreen", "frameborder", "scrolling"],
  FORCE_BODY: true,
});

// Parse and execute scripts from the sanitized embed code
const temp = document.createElement("div");
temp.innerHTML = sanitized;

// Move non-script nodes and re-create script tags to execute them
Array.from(temp.childNodes).forEach((node) => {
  if (node instanceof HTMLScriptElement) {
    const script = document.createElement("script");
    // Only allow scripts with external src — strip inline script content for safety
    if (node.src) {
      script.src = node.src;
      if (node.async) script.async = true;
      if (node.defer) script.defer = true;
      Array.from(node.attributes).forEach((attr) => {
        if (!["src", "async", "defer"].includes(attr.name)) {
          script.setAttribute(attr.name, attr.value);
        }
      });
      container.appendChild(script);
    }
  } else {
    container.appendChild(node.cloneNode(true));
  }
});

