// Build return URL — validate against allowed origins to prevent open redirect
const ALLOWED_ORIGINS = new Set([
  "https://rankora.co",
  "https://www.rankora.co",
  "http://localhost:8080",
  "http://localhost:5173",
]);
let baseReturnUrl = `${req.headers.get("origin") || "https://rankora.co"}/payment/callback`;
if (typeof return_url === "string" && return_url) {
  try {
    const parsed = new URL(return_url);
    if (ALLOWED_ORIGINS.has(parsed.origin)) {
      baseReturnUrl = return_url;
    } else {
      console.warn("Rejected return_url with disallowed origin:", parsed.origin);
