// @ts-nocheck
// deno-lint-ignore-file no-explicit-any
/// <reference lib="deno.ns" />
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
import DodoPayments from "https://esm.sh/dodopayments@2.4.1";
import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SUPABASE_ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const DODO_API_KEY = Deno.env.get("DODO_PAYMENTS_API_KEY");
    const DODO_ENV = Deno.env.get("DODO_PAYMENTS_ENVIRONMENT") || "test_mode";

    if (!DODO_API_KEY) {
      return new Response(
        JSON.stringify({ error: "Dodo Payments API key not configured" }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // Authenticate user
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUser = createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    const body = await req.json();
    const { topup_amount, plan_id, return_url } = body as Record<string, unknown>;

    if (!topup_amount && !plan_id) {
      return new Response(JSON.stringify({ error: "topup_amount or plan_id required" }), {
        status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    let productId: string;
    let amount: number;
    let credits: number;
    let currency = "USD";
    let itemName: string;
    let itemType: "topup" | "plan";
    let itemId: string | null = null;

    if (topup_amount) {
      // ─── WALLET TOP-UP FLOW ───
      const topupNum = Number(topup_amount);
      if (isNaN(topupNum) || topupNum <= 0) {
        return new Response(JSON.stringify({ error: "Invalid topup_amount" }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      // Get platform config for min amount, per-resume cost, and dodo product id
      const { data: config, error: configError } = await supabase
        .from("platform_config")
        .select("topup_min_amount, payg_per_resume_cost, topup_dodo_product_id")
        .limit(1)
        .single();

      if (configError || !config) {
        return new Response(JSON.stringify({ error: "Platform config not found" }), {
          status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const minAmount = config.topup_min_amount ?? 1;
      if (topupNum < minAmount) {
        return new Response(JSON.stringify({ error: `Minimum top-up amount is $${minAmount}` }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      if (!config.topup_dodo_product_id) {
        return new Response(JSON.stringify({ error: "Wallet top-up not configured. Admin must create the Dodo product first." }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const perResumeCost = config.payg_per_resume_cost ?? 0.07;
      credits = Math.floor(topupNum / perResumeCost);
      if (credits < 1) {
        return new Response(JSON.stringify({ error: "Amount too small to purchase any credits" }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      productId = config.topup_dodo_product_id;
      amount = Math.round(topupNum * 100); // cents
      itemName = `Wallet Top-Up $${topupNum}`;
      itemType = "topup";
    } else {
      // ─── PLAN SUBSCRIPTION FLOW (unchanged) ───
      const { data: plan, error } = await supabase
        .from("plans")
        .select("*")
        .eq("id", plan_id)
        .eq("active", true)
        .single();
      if (error || !plan) {
        return new Response(JSON.stringify({ error: "Plan not found or inactive" }), {
          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      if (!plan.dodo_product_id) {
        return new Response(JSON.stringify({ error: "This plan is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      productId = plan.dodo_product_id;
      amount = Math.round(plan.price * 100);
      credits = plan.credits;
      itemName = plan.name;
      itemType = "plan";
      itemId = String(plan_id);
    }

    // Build return URL
    const baseReturnUrl =
      (typeof return_url === "string" && return_url) ||
      `${req.headers.get("origin") || "https://rankora.co"}/payment/callback`;

    // 1) Create local payment record
    const insertPayload: any = {
      user_id: user.id,
      amount,
      currency,
      credits_purchased: credits,
      status: "created",
      payment_gateway: "dodo",
    };
    if (itemType === "plan" && itemId) {
      insertPayload.plan_id = itemId;
    }

    const insertRes = await supabase
      .from("payments")
      .insert(insertPayload)
      .select("id")
      .single();

    if (insertRes.error || !insertRes.data) {
      console.error("Failed to create local payment record:", insertRes.error?.message);
      await logSystemError({
        function_name: "create-dodo-checkout",
        error_type: "PAYMENT_RECORD_CREATE",
        severity: "critical",
        error_message: `Failed to create local payment record: ${insertRes.error?.message}`,
        user_id: user.id,
      });
      return new Response(JSON.stringify({ error: "Failed to create local payment record" }), {
        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const localPaymentId = insertRes.data.id as string;
    const returnUrlWithLocalPaymentId = `${baseReturnUrl}${baseReturnUrl.includes("?") ? "&" : "?"}local_payment_id=${encodeURIComponent(localPaymentId)}`;

    // 2) Create Dodo Checkout Session
    const isLive = DODO_ENV === "live_mode";
    const client = new DodoPayments({
      bearerToken: DODO_API_KEY,
      baseURL: isLive
        ? "https://live.dodopayments.com"
        : "https://test.dodopayments.com",
    });

    const cartItem: any = { product_id: productId, quantity: 1 };
    if (itemType === "topup") {
      cartItem.amount = amount; // dynamic amount in cents for PWYW product
    }

    const session = await client.checkoutSessions.create({
      product_cart: [cartItem],
      customer: {
        email: user.email ?? "",
        name: user.email?.split("@")[0] || "Customer",
      },
      billing_address: {
        street: "NA",
        city: "NA",
        state: "NA",
        country: "US",
        zipcode: "00000",
      },
      return_url: returnUrlWithLocalPaymentId,
      metadata: {
        local_payment_id: localPaymentId,
        user_id: user.id,
        item_type: itemType,
        item_id: itemId || "",
        item_name: itemName,
        credits: String(credits),
      } as Record<string, string>,
    });

    // 3) Persist the Dodo checkout session id
    if ((session as Record<string, unknown>).session_id) {
      await supabase
        .from("payments")
        .update({ dodo_checkout_session_id: (session as Record<string, string>).session_id })
        .eq("id", localPaymentId);
    }

    return new Response(
      JSON.stringify({
        checkout_url: (session as Record<string, string>).checkout_url,
        checkout_session_id: (session as Record<string, string>).session_id,
        payment_id: localPaymentId,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (err: unknown) {
    console.error("create-dodo-checkout error:", err);
    await logSystemError({
      function_name: "create-dodo-checkout",
      error_type: "CHECKOUT_ERROR",
      severity: "critical",
      error_message: errorToMessage(err),
      error_stack: errorToStack(err),
    });
    return new Response(
      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  }
});

