import { useState, useEffect } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { toast } from "sonner";
import {
  Loader2, CheckCircle, AlertCircle, RefreshCw,
  Copy, ExternalLink, Link2, XCircle, ShieldCheck, AlertTriangle,
} from "lucide-react";

interface VerifyResult {
  exists: boolean;
  is_active?: boolean;
  dodo_name?: string;
  dodo_price?: {
    price?: number;
    type?: string;
    pay_what_you_want?: boolean;
    pay_what_you_want_min_price?: number;
  };
  product?: any;
  error?: string;
}

const WalletSettingsTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState<"cost" | "min" | null>(null);
  const [syncing, setSyncing] = useState(false);
  const [verifying, setVerifying] = useState(false);
  const [linking, setLinking] = useState(false);
  const [minAmount, setMinAmount] = useState("");
  const [perCost, setPerCost] = useState("");
  const [manualProductId, setManualProductId] = useState("");
  const [showManualLink, setShowManualLink] = useState(false);
  const [verifyResult, setVerifyResult] = useState<VerifyResult | null>(null);

  const { data: config, isLoading } = useQuery({
    queryKey: ["platform_config_wallet"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("platform_config")
        .select("payg_per_resume_cost, topup_min_amount, topup_dodo_product_id")
        .limit(1).single();
      if (error) throw error;
      return data as any;
    },
    refetchOnWindowFocus: false,
  });

  const perResumeCost = parseFloat(perCost || String(config?.payg_per_resume_cost ?? 0.07)) || 0.07;
  const configMin = config?.topup_min_amount ?? 1;

  const runVerify = async (pid: string): Promise<VerifyResult> => {
    const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
      body: { action: "verify", product_id: pid },
    });
    if (error) throw error;
    return data as VerifyResult;
  };

  useEffect(() => {
    if (config?.topup_dodo_product_id && !verifyResult) {
      runVerify(config.topup_dodo_product_id).then(setVerifyResult).catch(() => {});
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config?.topup_dodo_product_id]);

  const handleSave = async (field: "cost" | "min") => {
    const val = field === "cost"
      ? parseFloat(perCost || String(config?.payg_per_resume_cost ?? 0.07))
      : parseFloat(minAmount || String(configMin));
    if (field === "min" && (isNaN(val) || val < 0.5)) { toast.error("Minimum must be at least $0.50"); return; }
    if (field === "cost" && (isNaN(val) || val <= 0)) { toast.error("Cost must be greater than $0"); return; }
    setSaving(field);
    try {
      const col = field === "cost" ? "payg_per_resume_cost" : "topup_min_amount";
      await supabase.from("platform_config").update({ [col]: val } as any).not("id", "is", null);
      if (field === "min" && config?.topup_dodo_product_id) {
        await supabase.functions.invoke("manage-dodo-product", {
          body: { action: "update", product_id: config.topup_dodo_product_id, type: "pack", price: val, pay_what_you_want: true, pwyw_min_price: val },
        });
      }
      toast.success("Saved");
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      qc.invalidateQueries({ queryKey: ["platform_config"] });
      qc.invalidateQueries({ queryKey: ["platform_config_topup"] });
    } catch (err: any) {
      toast.error(err.message || "Failed");
    } finally { setSaving(null); }
  };

  const handleVerify = async () => {
    if (!config?.topup_dodo_product_id) return;
    setVerifying(true);
    try {
      const r = await runVerify(config.topup_dodo_product_id);
      setVerifyResult(r);
      if (!r.exists) {
        await supabase.from("platform_config").update({ topup_dodo_product_id: null } as any).not("id", "is", null);
        qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
        toast.error("Not found on Dodo — link cleared");
      }
    } catch (err: any) {
      setVerifyResult({ exists: false, error: err.message });
    } finally { setVerifying(false); }
  };

  const handleLinkManual = async () => {
    const pid = manualProductId.trim();
    if (!pid) return;
    setLinking(true);
    try {
      const r = await runVerify(pid);
      setVerifyResult(r);
      if (!r.exists) { toast.error("Product not found on Dodo"); return; }
      await supabase.from("platform_config").update({ topup_dodo_product_id: pid } as any).not("id", "is", null);
      setManualProductId(""); setShowManualLink(false);
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      toast.success("Linked ✓");
    } catch (err: any) { toast.error(err.message); } finally { setLinking(false); }
  };

  const handleCreate = async () => {
    const minVal = parseFloat(minAmount || String(configMin)) || 1;
    setSyncing(true);
    try {
      const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
        body: { action: "create", type: "pack", name: "Wallet Top-Up", price: minVal, credits: 0, description: "Custom wallet recharge — credits calculated at checkout.", pay_what_you_want: true, pwyw_min_price: minVal, pwyw_max_price: 1000 },
      });
      if (error || data?.error) throw error || new Error(data.error);
      const pid = data?.product_id;
      if (!pid) throw new Error("No product ID returned");
      await supabase.from("platform_config").update({ topup_dodo_product_id: pid } as any).not("id", "is", null);
      qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
      const r = await runVerify(pid);
      setVerifyResult(r);
      toast.success("Created & linked ✓");
    } catch (err: any) { toast.error(err.message); } finally { setSyncing(false); }
  };

  const handleUnlink = async () => {
    await supabase.from("platform_config").update({ topup_dodo_product_id: null } as any).not("id", "is", null);
    qc.invalidateQueries({ queryKey: ["platform_config_wallet"] });
    setVerifyResult(null);
    toast.success("Unlinked");
  };

  const handleCopy = async (t: string) => { await navigator.clipboard.writeText(t); toast.success("Copied"); };

  if (isLoading) return <div className="flex items-center justify-center py-12"><Loader2 className="h-4 w-4 animate-spin text-muted-foreground" /></div>;

  const linkedId = config?.topup_dodo_product_id as string | null;

  // Derived product info
  const product = verifyResult?.exists ? (() => {
    const p = verifyResult.product || {};
    const priceObj = verifyResult.dodo_price || p.price || {};
    const pwyw = priceObj.pay_what_you_want ?? p.pay_what_you_want ?? false;
    const dodoPwywMin = pwyw ? (priceObj.pay_what_you_want_min_price ?? 0) / 100 : 0;
    const effectiveMin = dodoPwywMin > 0 ? dodoPwywMin : configMin;
    const minFromDodo = dodoPwywMin > 0;
    const isActive = verifyResult.is_active ?? true;
    const name = verifyResult.dodo_name || p.name || "Unknown";
    const taxCategory = p.tax_category || "saas";
    return { name, pwyw, effectiveMin, minFromDodo, isActive, taxCategory };
  })() : null;

  const previewCredits = Math.floor(10 / perResumeCost);

  return (
    <Card>
      <CardContent className="p-5 space-y-5">

        {/* Pricing row */}
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1.5">
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Cost per credit</p>
            <div className="flex gap-2">
              <div className="relative">
                <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                <Input type="number" step="0.01" min="0.01" className="pl-6 h-8 text-sm w-24"
                  value={perCost || String(config?.payg_per_resume_cost ?? 0.07)}
                  onChange={(e) => setPerCost(e.target.value)} />
              </div>
              <Button size="sm" className="h-8" onClick={() => handleSave("cost")} disabled={saving === "cost"}>
                {saving === "cost" ? <Loader2 className="h-3 w-3 animate-spin" /> : "Save"}
              </Button>
            </div>
          </div>
          <div className="space-y-1.5">
            <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Min top-up</p>
            <div className="flex gap-2">
              <div className="relative">
                <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                <Input type="number" step="0.5" min="0.5" className="pl-6 h-8 text-sm w-24"
                  value={minAmount || String(configMin)}
                  onChange={(e) => setMinAmount(e.target.value)} />
              </div>
              <Button size="sm" className="h-8" onClick={() => handleSave("min")} disabled={saving === "min"}>
                {saving === "min" ? <Loader2 className="h-3 w-3 animate-spin" /> : "Save"}
              </Button>
            </div>
          </div>
        </div>

        {/* Credit rate preview — inline pill */}
        <p className="text-xs text-muted-foreground">
          $10 → <span className="font-medium text-foreground">{previewCredits} credits</span>
          <span className="ml-1 text-muted-foreground/60">(floor(10 ÷ {perResumeCost}))</span>
        </p>

        <Separator />

        {/* Dodo Product */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-sm font-medium">Dodo Product</p>
            {linkedId && (
              <div className="flex items-center gap-1">
                <Button variant="ghost" size="sm" className="h-7 px-2 text-xs" onClick={handleVerify} disabled={verifying}>
                  {verifying ? <Loader2 className="h-3 w-3 animate-spin" /> : <RefreshCw className="h-3 w-3" />}
                </Button>
                <Button variant="ghost" size="sm" className="h-7 px-2 text-xs" onClick={() => handleCopy(linkedId)}>
                  <Copy className="h-3 w-3" />
                </Button>
                <a href={`https://app.dodopayments.com/products/edit?id=${linkedId}`} target="_blank" rel="noopener noreferrer">
                  <Button variant="ghost" size="sm" className="h-7 px-2"><ExternalLink className="h-3 w-3" /></Button>
                </a>
                <Button variant="ghost" size="sm" className="h-7 px-2 text-destructive hover:text-destructive" onClick={handleUnlink}>
                  <XCircle className="h-3 w-3" />
                </Button>
              </div>
            )}
          </div>

          {linkedId ? (
            <div className="space-y-2">
              {/* Product ID */}
              <code className="text-[11px] text-muted-foreground font-mono">{linkedId}</code>

              {/* Product status card */}
              {verifyResult ? (
                verifyResult.exists && product ? (
                  <div className={`rounded-lg border px-3 py-2.5 ${product.isActive ? "border-emerald-200 bg-emerald-50/50 dark:bg-emerald-950/20" : "border-amber-200 bg-amber-50/50"}`}>
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <ShieldCheck className={`h-3.5 w-3.5 ${product.isActive ? "text-emerald-600" : "text-amber-500"}`} />
                        <span className="text-sm font-medium">{product.name}</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        {product.isActive
                          ? <Badge className="text-[10px] h-5 bg-emerald-100 text-emerald-700 border-emerald-200 hover:bg-emerald-100">Active</Badge>
                          : <Badge variant="outline" className="text-[10px] h-5 text-amber-600 border-amber-300">Inactive</Badge>}
                        {product.pwyw
                          ? <Badge className="text-[10px] h-5 bg-blue-100 text-blue-700 border-blue-200 hover:bg-blue-100">PWYW on</Badge>
                          : <Badge variant="outline" className="text-[10px] h-5 text-destructive border-destructive/30">PWYW off</Badge>}
                        <Badge variant="outline" className="text-[10px] h-5 text-muted-foreground">
                          min ${product.effectiveMin}{!product.minFromDodo && <span className="text-amber-500 ml-0.5">*</span>}
                        </Badge>
                        <Badge variant="outline" className="text-[10px] h-5 text-muted-foreground capitalize">{product.taxCategory}</Badge>
                      </div>
                    </div>
                    {/* Warnings */}
                    {!product.pwyw && (
                      <p className="text-[11px] text-amber-700 mt-2 flex items-center gap-1">
                        <AlertTriangle className="h-3 w-3 shrink-0" />
                        PWYW is off — enable "Pay What You Want" in Dodo dashboard for this product.
                      </p>
                    )}
                    {!product.minFromDodo && product.pwyw && (
                      <p className="text-[11px] text-muted-foreground mt-1.5">
                        * Dodo PWYW min not set — app enforces ${product.effectiveMin}. Click Save on Min Top-Up to sync.
                      </p>
                    )}
                  </div>
                ) : (
                  <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2.5 flex items-center gap-2">
                    <AlertCircle className="h-3.5 w-3.5 text-destructive shrink-0" />
                    <p className="text-xs text-destructive">{verifyResult.error || "Product not found on Dodo — click Recreate."}</p>
                    <Button size="sm" className="h-6 text-xs ml-auto" onClick={handleCreate} disabled={syncing}>
                      {syncing ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : null}Recreate
                    </Button>
                  </div>
                )
              ) : (
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <Loader2 className="h-3 w-3 animate-spin" />Verifying…
                </div>
              )}
            </div>
          ) : (
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <Badge variant="outline" className="gap-1 text-xs text-muted-foreground">
                  <AlertCircle className="h-3 w-3" />Not linked
                </Badge>
                <Button size="sm" className="h-7 text-xs" onClick={handleCreate} disabled={syncing}>
                  {syncing ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : null}Create on Dodo
                </Button>
                <Button variant="ghost" size="sm" className="h-7 text-xs text-muted-foreground" onClick={() => setShowManualLink(!showManualLink)}>
                  <Link2 className="h-3 w-3 mr-1" />Link existing
                </Button>
              </div>

              {showManualLink && (
                <div className="flex gap-2">
                  <Input className="text-xs font-mono h-8" placeholder="pdt_xxxxxxxxxxxxxxxxxxxx"
                    value={manualProductId} onChange={(e) => setManualProductId(e.target.value)} />
                  <Button size="sm" className="h-8 shrink-0" onClick={handleLinkManual} disabled={linking || !manualProductId.trim()}>
                    {linking ? <Loader2 className="h-3 w-3 animate-spin mr-1" /> : <CheckCircle className="h-3 w-3 mr-1" />}Verify & Link
                  </Button>
                </div>
              )}

              {verifyResult && !verifyResult.exists && (
                <p className="text-xs text-destructive">{verifyResult.error || "Product not found."}</p>
              )}
            </div>
          )}

          <p className="text-[11px] text-muted-foreground">
            Tax is calculated automatically by Dodo based on customer location (VAT, GST, sales tax).
          </p>
        </div>

      </CardContent>
    </Card>
  );
};

export default WalletSettingsTab;

