} else if (weightStrategy === "custom" && Object.keys(weightOverrides).length > 0) {
  // Use admin-specified overrides, default to 1.0 for unspecified
  for (const dim of dimensions) {
    rawWeights[dim.key] = weightOverrides[dim.key] ?? 1.0;
  }
} else {
  // priority_boosted (default)
  const criticalKeys = new Set<string>();
  for (const dim of dimensions) {
    const keyLower = dim.key.toLowerCase();
    const labelLower = dim.label.toLowerCase();
    if (keyLower.includes("skill") || keyLower.includes("tool") || keyLower.includes("experience")) {
      criticalKeys.add(dim.key);
    }
    for (const p of priorities) {
      if (labelLower.includes(p) || p.includes(labelLower)) {
        criticalKeys.add(dim.key);
      }
    }
  }
  for (const dim of dimensions) {
    rawWeights[dim.key] = criticalKeys.has(dim.key) ? 2.0 : 1.0;
  }
}

// Normalize to sum to 1.0 with min 0.05 and max 0.50
const totalRaw = Object.values(rawWeights).reduce((a, b) => a + b, 0);
const weights: Record<string, number> = {};
for (const [key, raw] of Object.entries(rawWeights)) {
  let normalized = raw / totalRaw;
  normalized = Math.max(0.05, Math.min(0.50, normalized));
  weights[key] = normalized;
}
// Re-normalize after clamping
const totalClamped = Object.values(weights).reduce((a, b) => a + b, 0);
for (const key of Object.keys(weights)) {
  weights[key] = Math.round((weights[key] / totalClamped) * 1000) / 1000;
}
// Fix rounding to exactly 1.0
const finalTotal = Object.values(weights).reduce((a, b) => a + b, 0);

