import { describe, it, expect, vi, beforeEach } from "vitest";

// Mock DOM APIs needed by csvExport
beforeEach(() => {
  vi.stubGlobal("URL", {
    createObjectURL: vi.fn(() => "blob:mock-url"),
    revokeObjectURL: vi.fn(),
  });
});

describe("exportToCSV", () => {
  it("should handle empty data without throwing", async () => {
    const { exportToCSV } = await import("@/lib/csvExport");
    expect(() => exportToCSV([], "test")).not.toThrow();
  });

  it("should create CSV with correct headers and escaped values", async () => {
    const { exportToCSV } = await import("@/lib/csvExport");
    const clickSpy = vi.fn();
    vi.spyOn(document, "createElement").mockReturnValue({
      click: clickSpy,
      href: "",
      download: "",
    } as any);

    const data = [
      { name: "Alice", score: 95, notes: 'Has "great" skills' },
      { name: "Bob", score: 72, notes: "Needs improvement" },
    ];

    exportToCSV(data, "candidates");
    expect(clickSpy).toHaveBeenCalled();
  });

  it("should handle null and undefined values gracefully", async () => {
    const { exportToCSV } = await import("@/lib/csvExport");
    vi.spyOn(document, "createElement").mockReturnValue({
      click: vi.fn(),
      href: "",
      download: "",
    } as any);

    const data = [
      { name: "Alice", score: null, email: undefined },
    ];

    expect(() => exportToCSV(data, "test")).not.toThrow();
  });
});

