/**
 * Pure validation logic for ranking form submission.
 * Extracted from JobDetailView for testability.
 */

interface ValidateRankingParams {
  isNewJobMode: boolean;
  jobDescription: string;
  fileCount: number;
  subscriptionCredits: number;
  topupCredits: number;
  totalCredits: number;
  maxResumes: number;
  isAuthenticated: boolean;
}

export function validateRanking(params: ValidateRankingParams): string[] {
  const { isNewJobMode, jobDescription, fileCount, subscriptionCredits, topupCredits, totalCredits, maxResumes, isAuthenticated } = params;
  const errors: string[] = [];

  if (isNewJobMode && !jobDescription.trim()) {
    errors.push("Job description is required.");
  }

  if (fileCount === 0) {
    errors.push("Upload at least one resume.");
  }

  if (isAuthenticated) {
    const splitTotal = subscriptionCredits + topupCredits;
    const effectiveCredits = splitTotal > 0 ? splitTotal : totalCredits;
    const required = Math.min(fileCount, maxResumes);
    if (effectiveCredits < required) {
      errors.push(`Not enough credits. You need ${required} but have ${effectiveCredits}.`);
    }
  }

  return errors;
}

