import { describe, it, expect } from "vitest";
import { validateRanking } from "@/lib/validateRanking";

const baseParams = {
  isNewJobMode: true,
  jobDescription: "Looking for a React developer",
  fileCount: 3,
  subscriptionCredits: 10,
  topupCredits: 5,
  totalCredits: 15,
  maxResumes: 10,
  isAuthenticated: true,
};

describe("validateRanking", () => {
  it("should return no errors for valid input", () => {
    const errors = validateRanking(baseParams);
    expect(errors).toHaveLength(0);
  });

  it("should require job description in new job mode", () => {
    const errors = validateRanking({ ...baseParams, jobDescription: "" });
    expect(errors).toContain("Job description is required.");
  });

  it("should require job description with only whitespace in new job mode", () => {
    const errors = validateRanking({ ...baseParams, jobDescription: "   " });
    expect(errors).toContain("Job description is required.");
  });

  it("should not require job description in existing job mode", () => {
    const errors = validateRanking({ ...baseParams, isNewJobMode: false, jobDescription: "" });
    expect(errors).not.toContain("Job description is required.");
  });

  it("should require at least one resume", () => {
    const errors = validateRanking({ ...baseParams, fileCount: 0 });
    expect(errors).toContain("Upload at least one resume.");
  });

  it("should check credits against file count", () => {
    const errors = validateRanking({
      ...baseParams,
      fileCount: 5,
      subscriptionCredits: 2,
      topupCredits: 1,
      totalCredits: 3,
    });
    expect(errors).toContain("Not enough credits. You need 5 but have 3.");
  });

  it("should use totalCredits as fallback when split credits are 0", () => {
    const errors = validateRanking({
      ...baseParams,
      fileCount: 3,
      subscriptionCredits: 0,
      topupCredits: 0,
      totalCredits: 5,
    });
    expect(errors).toHaveLength(0);
  });

  it("should cap required credits at maxResumes", () => {
    const errors = validateRanking({
      ...baseParams,
      fileCount: 20,
      maxResumes: 10,
      subscriptionCredits: 10,
      topupCredits: 0,
      totalCredits: 10,
    });
    expect(errors).toHaveLength(0);
  });

  it("should not check credits for unauthenticated users", () => {
    const errors = validateRanking({
      ...baseParams,
      isAuthenticated: false,
      subscriptionCredits: 0,
      topupCredits: 0,
      totalCredits: 0,
    });
    // Only fileCount > 0 matters for unauthenticated
    expect(errors).toHaveLength(0);
  });

  it("should accumulate multiple errors", () => {
    const errors = validateRanking({
      ...baseParams,
      jobDescription: "",
      fileCount: 0,
    });
    expect(errors).toHaveLength(2);
    expect(errors).toContain("Job description is required.");
    expect(errors).toContain("Upload at least one resume.");
  });

  it("should handle exact credit match without error", () => {
    const errors = validateRanking({
      ...baseParams,
      fileCount: 5,
      subscriptionCredits: 3,
      topupCredits: 2,
      totalCredits: 5,
    });
    expect(errors).toHaveLength(0);
  });
});

