import type { Result } from "@/pages/Index";

/**
 * Generates a dedup key for a candidate result.
 * Uses candidate_name + candidate_email (normalized) for matching.
 * Falls back to filename if no candidate info available.
 */
function getCandidateKey(r: Result): string {
  const name = (r.candidate_name || "").trim().toLowerCase();
  const email = (r.candidate_email || "").trim().toLowerCase();

  // If we have email, it's the strongest identifier
  if (email) return `email:${email}`;
  // If we have a name, use it (handles "ALOK SINGH" case from screenshot)
  if (name && name !== "unknown") return `name:${name}`;
  // Fallback to filename (no dedup possible)
  return `file:${r.resume_id}`;
}

/**
 * Detects duplicate candidates in results.
 * Returns a Set of resume_ids that are duplicates (lower-scoring copies).
 * The highest-scoring entry for each candidate is NOT marked as duplicate.
 */
export function findDuplicateResumeIds(results: Result[]): Set<string> {
  const candidateGroups = new Map<string, Result[]>();

  for (const r of results) {
    if (r.pending) continue;
    const key = getCandidateKey(r);
    // Only group by candidate info keys, not file-based fallbacks
    if (key.startsWith("file:")) continue;
    const group = candidateGroups.get(key) || [];
    group.push(r);
    candidateGroups.set(key, group);
  }

  const duplicateIds = new Set<string>();
  for (const [, group] of candidateGroups) {
    if (group.length <= 1) continue;
    // Sort by score descending — first entry is the "original", rest are duplicates
    group.sort((a, b) => b.overall_score - a.overall_score);
    for (let i = 1; i < group.length; i++) {
      duplicateIds.add(group[i].resume_id);
    }
  }

  return duplicateIds;
}

