import { describe, it, expect } from "vitest";
import { findDuplicateResumeIds } from "@/lib/deduplicateCandidates";
import type { Result } from "@/pages/Index";

const makeResult = (overrides: Partial<Result> & { resume_id: string }): Result => ({
  id: overrides.resume_id + "-result",
  overall_score: 50,
  missing_skills: [],
  summary: null,
  interview_questions: null,
  filename: "resume.pdf",
  file_path: null,
  candidate_name: null,
  candidate_email: null,
  candidate_phone: null,
  ...overrides,
});

describe("findDuplicateResumeIds", () => {
  it("should return empty set when no duplicates", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "Alice", overall_score: 90 }),
      makeResult({ resume_id: "r2", candidate_name: "Bob", overall_score: 80 }),
    ];
    expect(findDuplicateResumeIds(results).size).toBe(0);
  });

  it("should detect duplicates by candidate_name", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "ALOK SINGH", overall_score: 81 }),
      makeResult({ resume_id: "r2", candidate_name: "ALOK SINGH", overall_score: 81 }),
      makeResult({ resume_id: "r3", candidate_name: "ALOK SINGH", overall_score: 81 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    // r1 is kept (first highest), r2 and r3 are duplicates
    expect(dupes.size).toBe(2);
    expect(dupes.has("r1")).toBe(false); // highest score kept
    expect(dupes.has("r2")).toBe(true);
    expect(dupes.has("r3")).toBe(true);
  });

  it("should keep the highest-scoring entry as non-duplicate", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "Jane Doe", overall_score: 60 }),
      makeResult({ resume_id: "r2", candidate_name: "Jane Doe", overall_score: 85 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    expect(dupes.size).toBe(1);
    expect(dupes.has("r1")).toBe(true); // lower score = duplicate
    expect(dupes.has("r2")).toBe(false); // higher score = kept
  });

  it("should detect duplicates by candidate_email", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "Alice Smith", candidate_email: "alice@example.com", overall_score: 90 }),
      makeResult({ resume_id: "r2", candidate_name: "A. Smith", candidate_email: "alice@example.com", overall_score: 70 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    expect(dupes.size).toBe(1);
    expect(dupes.has("r2")).toBe(true);
  });

  it("should be case-insensitive for names", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "ALOK SINGH", overall_score: 81 }),
      makeResult({ resume_id: "r2", candidate_name: "alok singh", overall_score: 81 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    expect(dupes.size).toBe(1);
  });

  it("should be case-insensitive for emails", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_email: "ALICE@EXAMPLE.COM", overall_score: 90 }),
      makeResult({ resume_id: "r2", candidate_email: "alice@example.com", overall_score: 70 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    expect(dupes.size).toBe(1);
  });

  it("should not flag entries with no candidate info as duplicates", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: null, candidate_email: null, overall_score: 50 }),
      makeResult({ resume_id: "r2", candidate_name: null, candidate_email: null, overall_score: 60 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    expect(dupes.size).toBe(0);
  });

  it("should not flag pending results", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "Alice", overall_score: 90, pending: true }),
      makeResult({ resume_id: "r2", candidate_name: "Alice", overall_score: 80, pending: true }),
    ];
    const dupes = findDuplicateResumeIds(results);
    expect(dupes.size).toBe(0);
  });

  it("should handle mix of unique and duplicate candidates", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "Alice", overall_score: 90 }),
      makeResult({ resume_id: "r2", candidate_name: "Bob", overall_score: 80 }),
      makeResult({ resume_id: "r3", candidate_name: "Alice", overall_score: 70 }),
      makeResult({ resume_id: "r4", candidate_name: "Charlie", overall_score: 60 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    expect(dupes.size).toBe(1);
    expect(dupes.has("r3")).toBe(true); // lower-scoring Alice
  });

  it("should prefer email-based matching over name-based", () => {
    const results = [
      makeResult({ resume_id: "r1", candidate_name: "Alice Smith", candidate_email: "alice@test.com", overall_score: 90 }),
      makeResult({ resume_id: "r2", candidate_name: "Alice Johnson", candidate_email: "alice@test.com", overall_score: 70 }),
    ];
    const dupes = findDuplicateResumeIds(results);
    // Same email = duplicate even though names differ
    expect(dupes.size).toBe(1);
    expect(dupes.has("r2")).toBe(true);
  });
});

