474→      }
475→
476→      try {
477→      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
478→      if (resumeProgress) {
479→        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
