132→function mergeSkillSynonyms(adminSynonyms: Record<string, string[]>) {
133→  const merged = { ...SKILL_SYNONYMS };
134→  for (const [canonical, syns] of Object.entries(adminSynonyms)) {
135→    const key = canonical.toLowerCase().trim();
136→    merged[key] = [...new Set([...(merged[key] || []), ...syns.map(s => s.toLowerCase().trim())])];
137→  }
138→  // Rebuild the lookup map
139→  for (const [canonical, syns] of Object.entries(merged)) {
140→    synonymToCanonical.set(canonical, canonical);
141→    for (const syn of syns) synonymToCanonical.set(syn, canonical);
142→  }
143→  return merged;
144→}
145→
146→function extractTotalYears(rolesWithDates: any[]): number {
147→  if (!Array.isArray(rolesWithDates) || rolesWithDates.length === 0) return 0;
148→
149→  const intervals: { start: number; end: number }[] = [];
150→  const currentYear = new Date().getFullYear();
151→  const currentMonth = new Date().getMonth() + 1;
152→
153→  for (const role of rolesWithDates) {
154→    const startRaw = role.start || role.start_date || role.from || "";
155→    const endRaw = role.end || role.end_date || role.to || "";
156→
157→    const startDate = parseDate(String(startRaw), currentYear, currentMonth);
158→    let endDate = parseDate(String(endRaw), currentYear, currentMonth);
159→
160→    // Handle "present", "current", "ongoing" etc.
161→    const endLower = String(endRaw).toLowerCase().trim();
162→    if (!endRaw || endLower === "present" || endLower === "current" || endLower === "ongoing" || endLower === "now" || endLower === "till date" || endLower === "till now") {
163→      endDate = currentYear + (currentMonth - 1) / 12;
164→    }
165→
166→    if (startDate > 0 && endDate > 0 && endDate >= startDate) {
167→      intervals.push({ start: startDate, end: endDate });
168→    }
169→  }
170→
171→  if (intervals.length === 0) return 0;
172→
173→  // Merge overlapping intervals to avoid double-counting
174→  intervals.sort((a, b) => a.start - b.start);
175→  const merged: { start: number; end: number }[] = [intervals[0]];
176→  for (let i = 1; i < intervals.length; i++) {
177→    const last = merged[merged.length - 1];
178→    if (intervals[i].start <= last.end) {
179→      last.end = Math.max(last.end, intervals[i].end);
180→    } else {
181→      merged.push(intervals[i]);
182→    }
183→  }
184→
185→  let totalYears = 0;
186→  for (const iv of merged) {
187→    totalYears += iv.end - iv.start;
188→  }
189→  return Math.round(totalYears * 10) / 10; // 1 decimal
190→}
191→
192→function parseDate(dateStr: string, currentYear: number, currentMonth: number): number {
193→  if (!dateStr) return 0;
194→  const s = dateStr.trim();
195→
196→  // Try "YYYY-MM" or "MM/YYYY" or "YYYY"
197→  const ymd = s.match(/^(\d{4})[\/\-](\d{1,2})/);
198→  if (ymd) return parseInt(ymd[1]) + (parseInt(ymd[2]) - 1) / 12;
199→
200→  const mdy = s.match(/^(\d{1,2})[\/\-](\d{4})/);
201→  if (mdy) return parseInt(mdy[2]) + (parseInt(mdy[1]) - 1) / 12;
202→
203→  // "Jan 2020", "January 2020"
204→  const monthYear = s.match(/^([a-zA-Z]+)\s+(\d{4})/);
205→  if (monthYear) {
206→    const month = monthNameToNum(monthYear[1]);
207→    if (month > 0) return parseInt(monthYear[2]) + (month - 1) / 12;
208→  }
209→
210→  // Plain year "2020"
211→  const plainYear = s.match(/^(\d{4})$/);
212→  if (plainYear) return parseInt(plainYear[1]);
213→
214→  return 0;
215→}
216→
217→function monthNameToNum(name: string): number {
218→  const months: Record<string, number> = {
219→    jan: 1, january: 1, feb: 2, february: 2, mar: 3, march: 3,
220→    apr: 4, april: 4, may: 5, jun: 6, june: 6,
221→    jul: 7, july: 7, aug: 8, august: 8, sep: 9, september: 9,
222→    oct: 10, october: 10, nov: 11, november: 11, dec: 12, december: 12,
223→  };
224→  return months[name.toLowerCase().trim()] || 0;
225→}
