712→    await logSystemError({ function_name: "rank-resumes", error_type: "GPT_SCORING", severity: "warning", error_message: errorToMessage(err), error_stack: errorToStack(err), resume_id: resumeId, job_id: jobId, user_id: userId });
713→
714→    // Heuristic fallback
715→    try {
716→      const allResumeTerms = extractResumeTerms(parsedJson);
717→      const mustHaves = jdAnalysis.critical_must_haves || [];
718→      const jdTools = jdAnalysis.tools || [];
719→      const totalKeywords = mustHaves.length + jdTools.length;
720→      let matchedCount = 0;
721→      const matchedSkills: string[] = [];
722→      const missingSkills: string[] = [];
723→
724→      for (const mh of mustHaves) {
725→        if (fuzzyMatch(mh, allResumeTerms)) { matchedCount++; matchedSkills.push(mh); }
726→        else { missingSkills.push(mh); }
