730→      }
731→
732→      const keywordScore = totalKeywords > 0 ? (matchedCount / totalKeywords) * 100 : 30;
733→      let similarity = 0.3;
734→      if (jdEmbedding) {
735→        const { data: simResult } = await supabase.rpc("match_resumes_by_embedding", {
736→          query_embedding: jdEmbedding, match_job_id: jobId, match_count: 1,
737→        });
738→        const match = (simResult || []).find((s: any) => s.id === resumeId);
739→        if (match) similarity = match.similarity;
740→      }
741→      let heuristicScore = Math.round(similarity * 100 * 0.6 + keywordScore * 0.4);
742→      const hFit = missingSkills.length === 0;
743→      if (!hFit) heuristicScore = Math.min(heuristicScore, cfg.hard_fit_cap);
744→      heuristicScore = Math.max(0, Math.min(100, heuristicScore));
745→
746→      const summary = `AI scoring unavailable — ranked by keyword match (${matchedCount}/${totalKeywords}).`;
747→      await supabase.from("resumes").update({ status: "done" }).eq("id", resumeId);
748→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
749→      const resultData = {
750→        resume_id: resumeId, job_id: jobId, scoring_version: "heuristic",
751→        overall_score: heuristicScore, hard_fit: hFit,
752→        confidence: Math.min(Math.round((matchedCount / Math.max(totalKeywords, 1)) * 40), 40),
753→        category_scores_json: {}, strengths_json: matchedSkills.slice(0, 5),
754→        gaps_json: missingSkills.slice(0, 5), interview_questions: [],
755→        explanation_json: { summary }, matched_must_haves: matchedSkills,
756→        missing_must_haves: missingSkills, missing_skills: missingSkills, summary,
757→        skill_score: null, experience_score: null, education_score: null,
758→      };
759→      if (existingResult) await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
760→      else await supabase.from("results").insert(resultData as any);
761→      return true;
762→    } catch (fallbackErr) {
763→      console.error(`Heuristic fallback also failed for ${resumeId}:`, fallbackErr);
764→      await supabase.from("resumes").update({ status: "failed" }).eq("id", resumeId);
765→      const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", resumeId).limit(1).single();
