768→          resume_id: resumeId, job_id: jobId, overall_score: 0, hard_fit: false,
769→          confidence: 0, category_scores_json: {}, strengths_json: [], gaps_json: [],
770→          summary: `Scoring failed: ${err instanceof Error ? err.message : "Unknown error"}`,
771→        } as any);
772→      }
773→      return false;
774→    }
775→  }
776→}
